61	</style>
62	</head>
63	<body>
64	<main class="calc">
65	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" role="status" aria-live="polite">0</div>
66	  <div class="keys">
67	    <button class="fn wide" data-testid="key-lparen" data-key="lparen" aria-label="open group">(</button>
68	    <button class="fn wide" data-testid="key-rparen" data-key="rparen" aria-label="close group">)</button>
69	    <button class="fn wide" data-testid="key-clear" data-key="clear">AC</button>
70	    <button class="fn" data-testid="key-sign" data-key="sign" aria-label="change sign">±</button>
71	    <button class="op" data-testid="key-div" data-key="div" aria-label="divide">÷</button>
72	    <button data-testid="key-7" data-key="7">7</button>
73	    <button data-testid="key-8" data-key="8">8</button>
74	    <button data-testid="key-9" data-key="9">9</button>
75	    <button class="op" data-testid="key-mul" data-key="mul" aria-label="multiply">×</button>
76	    <button class="op" data-testid="key-sub" data-key="sub" aria-label="subtract">−</button>
77	    <button data-testid="key-4" data-key="4">4</button>
78	    <button data-testid="key-5" data-key="5">5</button>
79	    <button data-testid="key-6" data-key="6">6</button>
80	    <button class="op" data-testid="key-add" data-key="add" aria-label="add">+</button>
81	    <button data-testid="key-1" data-key="1">1</button>
82	    <button data-testid="key-2" data-key="2">2</button>
83	    <button data-testid="key-3" data-key="3">3</button>
84	    <button class="wide" data-testid="key-0" data-key="0">0</button>
85	    <button data-testid="key-dot" data-key="dot" aria-label="decimal point">.</button>
86	    <button class="op" data-testid="key-equals" data-key="equals" aria-label="equals">=</button>
87	  </div>
