89	<script>
90	// Pure calculator logic. State: acc (stored left operand), op (pending operator),
91	// entry (digits being typed, or null), value (the current number, never rounded),
92	// error (true after a division by zero; only clear leaves it), stack (saved acc/op of each
93	// open group), closed (true right after `)`: value is a finished group result, not an entry).
94	var OPS = {
95	  add: function (a, b) { return a + b; },
96	  sub: function (a, b) { return a - b; },
97	  mul: function (a, b) { return a * b; },
98	  div: function (a, b) { return a / b; }
99	};
100	
101	function initialState() {
102	  return { acc: null, op: null, entry: null, value: 0, error: false, stack: [], closed: false };
103	}
104	
105	function errorState(v) {
106	  return { acc: null, op: null, entry: null, value: v, error: true, stack: [], closed: false };
107	}
108	
109	function press(s, key) {
110	  if (key === 'clear') return initialState();
111	
112	  // In the error state every key except clear is ignored.
113	  if (s.error) return s;
114	
115	  if (/^[0-9]$/.test(key)) {
116	    var entry = s.entry === null || s.entry === '0' ? key : s.entry === '-0' ? '-' + key : s.entry + key;
117	    return { acc: s.acc, op: s.op, entry: entry, value: Number(entry), error: false, stack: s.stack, closed: false };
118	  }
119	
120	  if (key === 'dot') {
121	    var e = s.entry === null ? '0' : s.entry;
122	    if (e.indexOf('.') !== -1) return s;
123	    e += '.';
124	    return { acc: s.acc, op: s.op, entry: e, value: Number(e), error: false, stack: s.stack, closed: false };
125	  }
126	
127	  // Sign and percent act on the current entry. Right after an operator there is no
128	  // entry yet, so they start one from 0. After a result or a closed group they act on the value.
129	  if (key === 'sign' || key === 'percent') {
130	    if (s.entry === null && (!s.op || s.closed)) {
131	      var nv = key === 'sign' ? -s.value : s.value / 100;
132	      return { acc: s.acc, op: s.op, entry: null, value: nv, error: false, stack: s.stack, closed: s.closed };
133	    }
134	    var cur = s.entry === null ? '0' : s.entry;
135	    var ne = key === 'sign' ? (cur[0] === '-' ? cur.slice(1) : '-' + cur) : shiftDecimal(cur, -2);
136	    return { acc: s.acc, op: s.op, entry: ne, value: Number(ne), error: false, stack: s.stack, closed: false };
137	  }
138	
139	  if (key in OPS) {
140	    // Operator right after another operator replaces it.
141	    if (s.op && s.entry === null && !s.closed) return { acc: s.acc, op: key, entry: null, value: s.value, error: false, stack: s.stack, closed: false };
142	    // Immediate execution: finish the waiting operation first, strictly left to right,
143	    // no precedence. The display always shows a real running result.
144	    var v = s.op ? OPS[s.op](s.acc, s.value) : s.value;
145	    if (!isFinite(v)) return errorState(v);
146	    return { acc: v, op: key, entry: null, value: v, error: false, stack: s.stack, closed: false };
147	  }
148	
149	  // `(` saves the waiting operation and starts a fresh one inside the group. It only
150	  // makes sense where a number could start, so it is ignored after an entry or a group.
151	  if (key === 'lparen') {
152	    if (s.entry !== null || s.closed) return s;
153	    var frame = { acc: s.acc, op: s.op };
154	    return { acc: null, op: null, entry: null, value: 0, error: false, stack: s.stack.concat([frame]), closed: false };
155	  }
156	
157	  // `)` finishes the group like equals, then restores the saved operation with the group
158	  // result as its right operand. Without an open group it is ignored.
159	  if (key === 'rparen') {
160	    if (!s.stack.length) return s;
161	    var g = s.op ? OPS[s.op](s.acc, s.value) : s.value;
162	    if (!isFinite(g)) return errorState(g);
163	    var top = s.stack[s.stack.length - 1];
164	    return { acc: top.acc, op: top.op, entry: null, value: g, error: false, stack: s.stack.slice(0, -1), closed: true };
165	  }
166	
167	  if (key === 'equals') {
168	    // Equals closes any groups left open.
169	    while (s.stack.length) {
170	      s = press(s, 'rparen');
171	      if (s.error) return s;
172	    }
173	    if (!s.op) return { acc: null, op: null, entry: null, value: s.value, error: false, stack: [], closed: false };
174	    var r = OPS[s.op](s.acc, s.value);
175	    if (!isFinite(r)) return errorState(r);
176	    return { acc: null, op: null, entry: null, value: r, error: false, stack: [], closed: false };
177	  }
178	
179	  return s;
180	}
181	
182	// Moves the decimal point of an entry string by n places, exactly, with no float noise.
183	// shiftDecimal('50', -2) is '0.5'.
184	function shiftDecimal(entry, n) {
185	  var sign = entry[0] === '-' ? '-' : '';
186	  var parts = entry.slice(sign.length).split('.');
187	  var digits = parts[0] + (parts[1] || '');
188	  var pos = parts[0].length + n;
189	  var str = pos <= 0 ? '0.' + '0'.repeat(-pos) + digits
190	    : pos >= digits.length ? digits + '0'.repeat(pos - digits.length)
191	    : digits.slice(0, pos) + '.' + digits.slice(pos);
192	  if (str.indexOf('.') !== -1) str = str.replace(/0+$/, '').replace(/\.$/, '');
193	  str = str.replace(/^0+(?=\d)/, '');
194	  return sign + str;
195	}
196	
197	// Presentation only: at most 10 significant digits, no trailing zeros, no separators.
198	// Exponential notation only when the rounded magnitude is >= 1e10 or < 1e-9.
199	function formatNumber(x) {
200	  var m = Math.abs(x).toExponential(9).split('e');
201	  var digits = m[0].replace('.', '');
202	  var exp = Number(m[1]);
203	  var sign = x < 0 ? '-' : '';
204	  if (x !== 0 && (exp >= 10 || exp < -9)) {
205	    return sign + m[0].replace(/\.?0+$/, '') + 'e' + m[1];
206	  }
207	  var int = exp >= 0 ? digits.slice(0, exp + 1) : '0';
208	  var frac = (exp >= 0 ? digits.slice(exp + 1) : '0'.repeat(-exp - 1) + digits).replace(/0+$/, '');
209	  return (int === '0' && frac === '' ? '' : sign) + int + (frac ? '.' + frac : '');
210	}
211	
212	// Visible text: the entry exactly as typed, Error, or the value formatted at render time.
213	function displayText(s) {
214	  if (s.error) return 'Error';
215	  if (s.entry !== null) return s.entry;
216	  return formatNumber(s.value);
217	}
218	
219	if (typeof document !== 'undefined') {
220	  var state = initialState();
221	  var display = document.querySelector('[data-testid="calc-display"]');
222	  var opButtons = document.querySelectorAll('[data-key="add"],[data-key="sub"],[data-key="mul"],[data-key="div"]');
223	
224	  function render() {
225	    display.textContent = displayText(state);
226	    display.setAttribute('data-value', String(state.value));
227	    display.setAttribute('data-error', state.error ? 'true' : 'false');
228	    for (var i = 0; i < opButtons.length; i++) {
229	      var b = opButtons[i];
230	      b.classList.toggle('active', state.op === b.dataset.key && state.entry === null && !state.closed);
231	    }
232	  }
233	
234	  document.querySelector('.keys').addEventListener('click', function (ev) {
235	    var btn = ev.target.closest('button');
236	    if (!btn) return;
237	    state = press(state, btn.dataset.key);
238	    render();
239	  });
240	
241	  var KEYMAP = { '.': 'dot', ',': 'dot', '+': 'add', '-': 'sub', '*': 'mul', 'x': 'mul', '/': 'div',
242	    '(': 'lparen', ')': 'rparen', '=': 'equals', 'Enter': 'equals', 'Escape': 'clear', 'c': 'clear', 'C': 'clear' };
243	  document.addEventListener('keydown', function (ev) {
244	    var key = /^[0-9]$/.test(ev.key) ? ev.key : KEYMAP[ev.key];
245	    if (!key || ev.ctrlKey || ev.metaKey || ev.altKey) return;
246	    ev.preventDefault();
247	    state = press(state, key);
248	    render();
249	  });
250	
251	  render();
252	}
253	</script>
254	</body>
255	</html>
